class FfiConverterBoolean: FfiConverter<bool, sbyte> {
    public static FfiConverterBoolean INSTANCE = new FfiConverterBoolean();

    public override bool Lift(sbyte value) {
        return value != 0;
    }

    public override bool Read(BigEndianStream stream) {
        return Lift(stream.ReadSByte());
    }

    public override sbyte Lower(bool value) {
        return value ? (sbyte)1 : (sbyte)0;
    }

    public override int AllocationSize(bool value) {
        return (sbyte)1;
    }

    public override void Write(bool value, BigEndianStream stream) {
        stream.WriteSByte(Lower(value));
    }
}



class FfiConverterString: FfiConverter<string, RustBuffer> {
    public static FfiConverterString INSTANCE = new FfiConverterString();

    // Note: we don't inherit from FfiConverterRustBuffer, because we use a
    // special encoding when lowering/lifting.  We can use `RustBuffer.len` to
    // store our length and avoid writing it out to the buffer.
    public override string Lift(RustBuffer value) {
        try {
            unsafe {
                return System.Text.Encoding.UTF8.GetString(
                    (byte*)value.data.ToPointer(), Convert.ToInt32(value.len));
            }
        } finally {
            RustBuffer.Free(value);
        }
    }

    public override string Read(BigEndianStream stream) {
        var length = stream.ReadInt();
        return stream.ReadUtf8String(length);
    }

    public override RustBuffer Lower(string value) {
        var rustBuffer = RustBuffer.Alloc(System.Text.Encoding.UTF8.GetByteCount(value));
        try {
            unsafe {
                fixed (char* chars = value) {
                    System.Text.Encoding.UTF8.GetBytes(
                        chars, value.Length, (byte*)rustBuffer.data.ToPointer(), Convert.ToInt32(rustBuffer.len));
                }
            }
            return rustBuffer;
        } catch {
            RustBuffer.Free(rustBuffer);
            throw;
        }
    }

    // TODO(CS)
    // We aren't sure exactly how many bytes our string will be once it's UTF-8
    // encoded.  Allocate 3 bytes per unicode codepoint which will always be
    // enough.
    public override int AllocationSize(string value) {
        const int sizeForLength = 4;
        var sizeForString = System.Text.Encoding.UTF8.GetByteCount(value);
        return sizeForLength + sizeForString;
    }

    public override void Write(string value, BigEndianStream stream) {
        stream.WriteUtf8String(value);
    }
}




class FfiConverterByteArray: FfiConverterRustBuffer<byte[]> {
    public static FfiConverterByteArray INSTANCE = new FfiConverterByteArray();

    public override byte[] Read(BigEndianStream stream) {
        var length = stream.ReadInt();
        return stream.ReadBytes(length);
    }

    public override int AllocationSize(byte[] value) {
        return 4 + value.Length;
    }

    public override void Write(byte[] value, BigEndianStream stream) {
        stream.WriteInt(value.Length);
        stream.WriteBytes(value);
    }
}



/// <summary>
/// The District AI core, as the Windows app holds it: one per process.
///
/// [`start`](Self::start) builds everything and starts the actor;
/// [`send`](Self::send), [`open_link`](Self::open_link),
/// [`suspend`](Self::suspend) and [`resume`](Self::resume) hand it events;
/// [`shell`](Self::shell) and
/// [`screen`](Self::screen) read the latest snapshot; and
/// [`shutdown`](Self::shutdown) gives the model its last word and stops the
/// runtime.
/// </summary>
public interface ICore {
    /// <summary>
    /// A notification the host showed was activated: its toast clicked
    /// (`action_id` `None`), or one of its buttons, named by its
    /// `NotificationActionView::action_id`. The model then opens what the
    /// notification is about, or answers or declines the call it names.
    ///
    /// `open_target` is the toast's `NotificationView::open_target`, as the
    /// toast carried it. It is read only for a click on the body of a toast
    /// this core does not remember (shown before the app last quit, say), so
    /// that the click still opens the thread or call it was about. A button
    /// on such a toast, or a target that does not read back, does nothing
    /// (see `NotificationTable::activate_toast`).
    /// </summary>
    void ActivateNotification(string @id, string? @actionId, string? @openTarget);
    /// <summary>
    /// Hands the model a `districtai:` link Windows activated the app with,
    /// and says what kind it was. A sign-in's answer goes to the sign-in, a
    /// hand-off's to the hand-off (the core checks each against what it is
    /// waiting for); anything else is ignored.
    /// </summary>
    LinkKind OpenLink(string @uri);
    /// <summary>
    /// A raw WNS push arrived, while the app ran or as what launched it.
    /// Returns whether it was one this build reads; a ring or a message is
    /// then handed to the model once the session can take it.
    /// </summary>
    bool PushReceived(string @payload);
    /// <summary>
    /// Registers the WNS channel `channel_uri` with the service, for the
    /// member signed in (crate::push): at sign-in, and each time Windows
    /// renews the channel. Says how it went, for the app's log; nothing in the
    /// app depends on it. The core's sign-out unregisters it.
    /// </summary>
    Task<PushRegistration> RegisterPushChannel(string @channelUri);
    /// <summary>
    /// The machine has woken: the model registers this desktop's presence
    /// again when it should ring. Nothing waits for that. Ignored before
    /// [`start`](Self::start) and after [`shutdown`](Self::shutdown).
    /// </summary>
    void Resume();
    /// <summary>
    /// The snapshot's revision: 0 until the model first changes what the
    /// window shows, then one more for each change.
    /// </summary>
    ulong Revision();
    /// <summary>
    /// The screen inside the frame, as of [`revision`](Self::revision).
    /// </summary>
    ScreenView Screen();
    /// <summary>
    /// Hands the model something the user did: each of its core events, in
    /// order. Ignored before [`start`](Self::start) and after
    /// [`shutdown`](Self::shutdown).
    /// </summary>
    void Send(UiEvent @event);
    /// <summary>
    /// The window's frame, as of [`revision`](Self::revision).
    /// </summary>
    ShellView Shell();
    /// <summary>
    /// Tells the model the app is quitting, gives the work it asks for (saving
    /// the session) up to [`QUIT_BUDGET`], and stops the runtime. Safe to call
    /// more than once, and before [`start`](Self::start).
    /// </summary>
    Task Shutdown();
    /// <summary>
    /// Builds the runtime and every adapter, and starts the model: it drains
    /// the revoke outbox and looks for a stored session.
    /// </summary>
    /// <exception cref="StartException"></exception>
    void Start(StartConfig @config, UiHost @host);
    /// <summary>
    /// The machine is about to sleep. Tells the model, which unregisters this
    /// desktop's presence and ends any call or ring, and returns once the work
    /// that asks for has run, or after [`SUSPEND_BUDGET`], whichever is first.
    /// The caller holds the sleep for that long and no longer. Returns at
    /// once before [`start`](Self::start) and after
    /// [`shutdown`](Self::shutdown).
    /// </summary>
    Task Suspend();
}
