    /// <summary>
    /// The legal business name.
    /// </summary>
    string BusinessName, 
    /// <summary>
    /// The tax or company number. Optional.
    /// </summary>
    string Ein, 
    /// <summary>
    /// The website. Optional.
    /// </summary>
    string Website, 
    /// <summary>
    /// The industry. Optional.
    /// </summary>
    string Vertical, 
    /// <summary>
    /// One of [`A2pView::campaign_types`]' values.
    /// </summary>
    string CampaignType, 
    /// <summary>
    /// What will be sent.
    /// </summary>
    string CampaignDescription, 
    /// <summary>
    /// An example message.
    /// </summary>
