    /// <summary>
    /// Close the form adding a contact. The core refuses while it is saving.
    /// </summary>
    public record CancelCreate: ContactsAction {}
    
    
    /// <summary>
    /// "Edit", on the open contact.
    /// </summary>
    public record StartEdit: ContactsAction {}
    
    
