/// <summary>
/// Which copy of the app a package is.
/// </summary>
public enum CopyFlavour: int {
    /// <summary>
    /// The Microsoft Store's copy.
    /// </summary>
    Store,
    /// <summary>
    /// The GitHub copy.
    /// </summary>
    GitHub,
    /// <summary>
    /// Neither: a development build, or a package this build does not know.
    /// </summary>
    Other
}

class FfiConverterTypeCopyFlavour: FfiConverterRustBuffer<CopyFlavour> {
    public static FfiConverterTypeCopyFlavour INSTANCE = new FfiConverterTypeCopyFlavour();

    public override CopyFlavour Read(BigEndianStream stream) {
        var value = stream.ReadInt();
        switch (value) {
            case 1: return CopyFlavour.Store;
            case 2: return CopyFlavour.GitHub;
            case 3: return CopyFlavour.Other;
            default: throw new InternalException(String.Format("invalid enum value '{0}' in FfiConverterTypeCopyFlavour.Read()", value));
        }
    }

    public override int AllocationSize(CopyFlavour value) {
        return 4;
    }

    public override void Write(CopyFlavour value, BigEndianStream stream) {
        switch (value) {
            case CopyFlavour.Store: stream.WriteInt(1); break;
            case CopyFlavour.GitHub: stream.WriteInt(2); break;
            case CopyFlavour.Other: stream.WriteInt(3); break;
            default: throw new InternalException(String.Format("invalid enum value '{0}' in FfiConverterTypeCopyFlavour.Write()", value));
        }
    }
}







/// <summary>
/// Something the member did on the help desk's screens.
/// </summary>
public record DeskAction {
    
    /// <summary>
    /// Open the help desk.
    /// </summary>
    public record Open: DeskAction {}
    
    
    /// <summary>
    /// Open a ticket.
    /// </summary>
    public record OpenTicket (
        string TicketId
    ) : DeskAction {}
    
    /// <summary>
    /// Open the help desk's settings.
    /// </summary>
    public record OpenSettings: DeskAction {}
    
    
    /// <summary>
    /// Show only the tickets `filter` picks.
    /// </summary>
    public record Filter (
        DeskFilter FilterValue
    ) : DeskAction {}
    
    /// <summary>
    /// Turn the desk on, from the switched-off state.
    /// </summary>
    public record TurnOn: DeskAction {}
    
    
    /// <summary>
    /// Open the form raising a ticket.
    /// </summary>
    public record StartTicket: DeskAction {}
    
    
    /// <summary>
    /// The form changed: the whole form as it now reads.
    /// </summary>
    public record EditTicket (
        string Subject,
        string Message,
        string RequesterName,
        string RequesterEmail,
        string RequesterPhone
    ) : DeskAction {}
    
    /// <summary>
    /// Raise the ticket, or try again after a failure.
    /// </summary>
    public record SubmitTicket: DeskAction {}
    
    
    /// <summary>
    /// Close the form, dropping what was typed.
    /// </summary>
    public record CancelTicket: DeskAction {}
    
    
    /// <summary>
    /// Put away the confirmation of a ticket raised.
    /// </summary>
    public record DismissSubmitted: DeskAction {}
    
    
    /// <summary>
    /// The open ticket's reply changed.
    /// </summary>
    public record EditReply (
        string Text
    ) : DeskAction {}
    
    /// <summary>
    /// Send the reply.
    /// </summary>
    public record SendReply: DeskAction {}
    
    
    /// <summary>
    /// Move the open ticket to `status`. Not asked first: every status can be
    /// moved back, and the answer shows at once.
    /// </summary>
    public record SetStatus (
        DeskStatus Status
    ) : DeskAction {}
    
    /// <summary>
    /// Put away the open ticket's failures.
    /// </summary>
    public record DismissTicketFailures: DeskAction {}
    
    
    /// <summary>
    /// The "desk on" switch.
    /// </summary>
    public record SetEnabled (
        bool On
    ) : DeskAction {}
    
    /// <summary>
    /// The "email customers" switch.
    /// </summary>
    public record SetNotify (
        bool On
    ) : DeskAction {}
    
    /// <summary>
    /// The name box changed.
    /// </summary>
    public record EditBrandName (
        string Name
    ) : DeskAction {}
    
    /// <summary>
    /// Save what changed.
    /// </summary>
    public record SaveSettings: DeskAction {}
    
    
    /// <summary>
    /// Publish a picked image as the logo. Refused here, and never sent, when
    /// [`desk_logo_problem`] has a reason.
    /// </summary>
    public record UploadLogo (
        PickedFileView File
    ) : DeskAction {}
    
    /// <summary>
    /// The picked logo could not be read at all.
    /// </summary>
    public record LogoUnreadable: DeskAction {}
    
    
    /// <summary>
    /// Take the logo down.
    /// </summary>
    public record DeleteLogo: DeskAction {}
    
    
    /// <summary>
    /// Put away the settings' failures and notes.
    /// </summary>
    public record DismissSettingsFailures: DeskAction {}
    
    

    
}

