    /// <summary>
    /// Show this tab.
    /// </summary>
    public record SelectTab (
        NumbersTab Tab
    ) : MarketplaceAction {}
    
    /// <summary>
    /// The search's filters changed: the core searches once the typing stops.
    /// </summary>
    public record EditSearch (
        string AreaCode,
        string Country,
        string NumberType
    ) : MarketplaceAction {}
    
    /// <summary>
    /// Search now (or again).
    /// </summary>
    public record Search: MarketplaceAction {}
    
    
    /// <summary>
    /// Manage a held number or the carrier account.
    /// </summary>
    public record Numbers (
        NumberAdminAction Action
    ) : MarketplaceAction {}
    

    
}

class FfiConverterTypeMarketplaceAction : FfiConverterRustBuffer<MarketplaceAction>{
    public static FfiConverterRustBuffer<MarketplaceAction> INSTANCE = new FfiConverterTypeMarketplaceAction();

    public override MarketplaceAction Read(BigEndianStream stream) {
        var value = stream.ReadInt();
        switch (value) {
            case 1:
                return new MarketplaceAction.Open(
                );
            case 2:
                return new MarketplaceAction.OpenWeb(
                );
            case 3:
                return new MarketplaceAction.SelectTab(
                    FfiConverterTypeNumbersTab.INSTANCE.Read(stream)
                );
            case 4:
                return new MarketplaceAction.EditSearch(
                    FfiConverterString.INSTANCE.Read(stream),
                    FfiConverterString.INSTANCE.Read(stream),
                    FfiConverterString.INSTANCE.Read(stream)
                );
            case 5:
                return new MarketplaceAction.Search(
                );
            case 6:
                return new MarketplaceAction.Numbers(
                    FfiConverterTypeNumberAdminAction.INSTANCE.Read(stream)
                );
            default:
                throw new InternalException(String.Format("invalid enum value '{0}' in FfiConverterTypeMarketplaceAction.Read()", value));
        }
    }

    public override int AllocationSize(MarketplaceAction value) {
        switch (value) {
            case MarketplaceAction.Open variant_value:
                return 4;
            case MarketplaceAction.OpenWeb variant_value:
                return 4;
            case MarketplaceAction.SelectTab variant_value:
                return 4
                    + FfiConverterTypeNumbersTab.INSTANCE.AllocationSize(variant_value.Tab);
            case MarketplaceAction.EditSearch variant_value:
                return 4
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.AreaCode)
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.Country)
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.NumberType);
            case MarketplaceAction.Search variant_value:
                return 4;
            case MarketplaceAction.Numbers variant_value:
                return 4
                    + FfiConverterTypeNumberAdminAction.INSTANCE.AllocationSize(variant_value.Action);
            default:
                throw new InternalException(String.Format("invalid enum value '{0}' in FfiConverterTypeMarketplaceAction.AllocationSize()", value));
        }
    }

    public override void Write(MarketplaceAction value, BigEndianStream stream) {
        switch (value) {
            case MarketplaceAction.Open variant_value:
                stream.WriteInt(1);
                break;
            case MarketplaceAction.OpenWeb variant_value:
                stream.WriteInt(2);
                break;
            case MarketplaceAction.SelectTab variant_value:
                stream.WriteInt(3);
                FfiConverterTypeNumbersTab.INSTANCE.Write(variant_value.Tab, stream);
                break;
            case MarketplaceAction.EditSearch variant_value:
                stream.WriteInt(4);
                FfiConverterString.INSTANCE.Write(variant_value.AreaCode, stream);
                FfiConverterString.INSTANCE.Write(variant_value.Country, stream);
                FfiConverterString.INSTANCE.Write(variant_value.NumberType, stream);
                break;
            case MarketplaceAction.Search variant_value:
                stream.WriteInt(5);
                break;
            case MarketplaceAction.Numbers variant_value:
                stream.WriteInt(6);
                FfiConverterTypeNumberAdminAction.INSTANCE.Write(variant_value.Action, stream);
                break;
            default:
                throw new InternalException(String.Format("invalid enum value '{0}' in FfiConverterTypeMarketplaceAction.Write()", value));
        }
    }
}







/// <summary>
/// A role, as the section offers it.
/// </summary>
public enum MemberRoleView: int {
    /// <summary>
    /// Full access, members included.
    /// </summary>
    Agency,
    /// <summary>
    /// Everyday use.
    /// </summary>
    Client,
    /// <summary>
    /// Read only.
    /// </summary>
    Viewer
}

class FfiConverterTypeMemberRoleView: FfiConverterRustBuffer<MemberRoleView> {
    public static FfiConverterTypeMemberRoleView INSTANCE = new FfiConverterTypeMemberRoleView();

    public override MemberRoleView Read(BigEndianStream stream) {
        var value = stream.ReadInt();
        switch (value) {
            case 1: return MemberRoleView.Agency;
            case 2: return MemberRoleView.Client;
            case 3: return MemberRoleView.Viewer;
            default: throw new InternalException(String.Format("invalid enum value '{0}' in FfiConverterTypeMemberRoleView.Read()", value));
        }
    }

    public override int AllocationSize(MemberRoleView value) {
        return 4;
    }

    public override void Write(MemberRoleView value, BigEndianStream stream) {
        switch (value) {
            case MemberRoleView.Agency: stream.WriteInt(1); break;
            case MemberRoleView.Client: stream.WriteInt(2); break;
            case MemberRoleView.Viewer: stream.WriteInt(3); break;
            default: throw new InternalException(String.Format("invalid enum value '{0}' in FfiConverterTypeMemberRoleView.Write()", value));
        }
    }
}







