/// <summary>
/// What the screen inside the frame shows.
/// </summary>
public record ScreenView {
    
    /// <summary>
    /// Everything outside a session: looking for a stored one, signed out,
    /// signing in through the browser, and signing out.
    /// </summary>
    public record Session (
        SessionScreen View
    ) : ScreenView {}
    
    /// <summary>
    /// The open workspace's overview.
    /// </summary>
    public record Overview (
        OverviewView View
    ) : ScreenView {}
    
    /// <summary>
    /// The conversations.
    /// </summary>
    public record Inbox (
        InboxView View
    ) : ScreenView {}
    
    /// <summary>
    /// One conversation.
    /// </summary>
    public record Thread (
        ThreadView View
    ) : ScreenView {}
    
    /// <summary>
    /// The call log.
    /// </summary>
    public record Calls (
        CallsView View
    ) : ScreenView {}
    
    /// <summary>
    /// One call.
    /// </summary>
    public record CallDetail (
        CallDetailView View
    ) : ScreenView {}
    
    /// <summary>
    /// The contacts.
    /// </summary>
    public record Contacts (
        ContactsView View
    ) : ScreenView {}
    
    /// <summary>
    /// One contact.
    /// </summary>
    public record ContactDetail (
        ContactDetailView View
    ) : ScreenView {}
    
    /// <summary>
    /// The account.
    /// </summary>
    public record Account (
        AccountView View
    ) : ScreenView {}
    
    /// <summary>
    /// The devices signed in to the account.
    /// </summary>
    public record Devices (
        DevicesView View
    ) : ScreenView {}
    
    /// <summary>
    /// The dialler, in a build that can carry calls.
    /// </summary>
    public record Dialer (
        DialerView View
    ) : ScreenView {}
    
    /// <summary>
    /// The callers the workspace has blocked.
    /// </summary>
    public record BlockedContacts (
        BlockedView View
    ) : ScreenView {}
    
    /// <summary>
    /// District HQ, the workspace assistant.
    /// </summary>
    public record Hq (
        HqView View
    ) : ScreenView {}
    
    /// <summary>
    /// Call analytics and metered usage.
    /// </summary>
    public record Analytics (
        AnalyticsView View
    ) : ScreenView {}
    
    /// <summary>
    /// The workspace's phone numbers: held, for sale (bought on the web), and
    /// managed (crate::numbers).
    /// </summary>
    public record Marketplace (
        MarketplaceView View
    ) : ScreenView {}
    
    /// <summary>
    /// The plan and invoices, read only.
    /// </summary>
    public record Billing (
        BillingView View
    ) : ScreenView {}
    
    /// <summary>
    /// Workflows and their runs.
    /// </summary>
    public record Workflows (
        WorkflowsView View
    ) : ScreenView {}
    
    /// <summary>
    /// Booking pages.
    /// </summary>
    public record Scheduling (
        SchedulingView View
    ) : ScreenView {}
    
    /// <summary>
    /// A section of the booking scheduler's administration, or a detail
    /// under one.
    /// </summary>
    public record SchedulingAdmin (
        SchedulingAdminView View
    ) : ScreenView {}
    
    /// <summary>
    /// The help desk's tickets.
    /// </summary>
    public record Desk (
        DeskView View
    ) : ScreenView {}
    
    /// <summary>
    /// One help desk ticket.
