/// <summary>
/// Where the session is. One variant per [`SessionState`] variant.
/// </summary>
public enum SessionPhase: int {
    /// <summary>
    /// Looking for a stored session.
    /// </summary>
    Restoring,
    /// <summary>
    /// Nobody is signed in.
    /// </summary>
    SignedOut,
    /// <summary>
    /// A sign-in is under way in the browser.
    /// </summary>
    SigningIn,
    /// <summary>
    /// Someone is signed in.
    /// </summary>
    SignedIn,
    /// <summary>
