                );
            case 3:
                return new StudioControlView.Switch(
                    FfiConverterBoolean.INSTANCE.Read(stream)
                );
            case 4:
                return new StudioControlView.Lines(
                    FfiConverterString.INSTANCE.Read(stream)
                );
